"""Code generated from the VIP probe and the binding (milestone M4): the derived configuration package, the bridge between the VIP interface and
the DUT pins, the VIP adapter, the tb_top block and the VIP part of the filelist. Only facts from `vip_integration.json` are used (DUT-DV-010);
the VIP is referenced by `vip_root` (an environment-variable expression or a relative path), never copied (DUT-DV-020)."""

from __future__ import annotations

import re
from pathlib import Path

from q3tui.flows.dv.uvm import svgen as g
from q3tui.flows.dv.uvm.contract import VerificationContract


def derived_globals(vip_dir: Path, probe: dict, binding: dict, hdr: str) -> str:
    """The VIP's constants package with the overridden parameters set to the approved DUT configuration (the VIP file itself is untouched)."""
    src = (vip_dir / probe["globals"]["file"]).read_text(errors="replace")
    lines = []
    for k, v in sorted(binding["config_overrides"].items()):
        old = probe["globals"]["parameters"][k]["value"]
        new, n = re.subn(rf"(parameter\s+(?:int|bit|longint)?\s*{k}\s*=\s*)[^;]+;", rf"\g<1>{v};  // was {old} in the VIP: approved DUT configuration", src, count=1)
        src = new
        lines.append(f"{k}: {old} -> {v}" if n else f"{k}: NOT FOUND")
    note = (f"// DERIVED VIP CONFIGURATION (generated by Q3TUI): a copy of {probe['globals']['file']} from the VIP with these constants changed to the\n"
            f"// approved DUT configuration: {'; '.join(lines)}. The VIP's own file is not edited (DUT-DV-020); this file replaces it in the filelist.\n")
    return hdr + note + src


def standin(sub: dict, hdr: str) -> str:
    """A unit with the same ports as a VIP unit the simulator cannot compile, with no behavior (see the binding's substitutions)."""
    ports = ",\n  ".join(f"input {p['width'] + ' ' if p['width'] else ''}{p['name']}" for p in sub["ports"])
    return (hdr + f"// STAND-IN for {sub['unit']} ({sub['file']} of the VIP). {sub['reason']}.\n"
            f"// Same ports, no properties: the VIP's own assertions are not run (recorded in vip_integration.json).\n"
            f"{sub['kind']} {sub['unit']}(\n  {ports}\n);\nend{sub['kind']}\n")


def standin_coverage(sub: dict, probe: dict, hdr: str) -> str:
    """Stand-in for the VIP's own coverage component: the same class name, the member the agent uses, no covergroup."""
    cc, pk = probe["coverage_class"], next(u["unit"] for u in probe["compile"]["order"] if u["unit"].endswith("master_pkg"))
    members = "\n".join(f"  {m['type']} {m['name']};" for m in cc["members"])
    return (hdr + f"// STAND-IN for {sub['unit']} ({sub['file']} of the VIP). {sub['reason']}.\n"
            f"`ifndef {sub['unit'].upper()}_INCLUDED_\n`define {sub['unit'].upper()}_INCLUDED_\n"
            f"class {sub['unit']} extends uvm_subscriber #({cc['item']});\n  `uvm_component_utils({sub['unit']})\n{members}\n"
            f'  function new(string name = "{sub["unit"]}", uvm_component parent = null);\n    super.new(name, parent);\n  endfunction\n'
            f"  function void write({cc['item']} t);\n  endfunction\nendclass : {sub['unit']}\n`endif\n")


def bridge(c: VerificationContract, probe: dict, binding: dict, hdr: str) -> str:
    """Connects the VIP interface to the DUT pins: only wires, from the signal map. No behavior."""
    vif = probe["interface"]["name"]
    out = []
    for m in binding["signal_map"]:
        if m.get("status") != "matched":
            continue
        if m["direction"] == "vip_to_dut" and re.search(r"(valid|ready)$", m["vip"]):
            # a control input of the DUT never carries X: a VIP may leave VALID/READY unknown until its first transfer (observed with axi4_avip), and an X
            # on a handshake input corrupts the DUT's state for the whole run. 1 only when the VIP drives a defined 1.
            out.append(f"  assign pins.{m['dut']} = (vip.{m['vip']} === 1'b1);  // X from the VIP is seen as 0")
        elif m["direction"] == "vip_to_dut":
            out.append(f"  assign pins.{m['dut']} = vip.{m['vip']};")
        else:
            out.append(f"  assign vip.{m['vip']} = pins.{m['dut']};")
    out += [f"  assign vip.{t} = '0;  // VIP input with no DUT port" for t in binding["tie_to_zero"]]
    return hdr + (f"// Wires between the VIP interface ({vif}) and the DUT pins, generated from the signal map of vip_integration.json.\n"
                  f"module dut_axi_bridge({vif} vip, dut_pins_if pins);\n" + "\n".join(out) + "\nendmodule\n")


def adapter(probe: dict, binding: dict, hdr: str) -> str:
    """The only code that uses the VIP's classes (DUT-DV-019): it creates the VIP master agent and turns a dut_axi_txn into VIP stimulus."""
    r, m = probe["roles"], probe["agent_members"]
    pk = next(u["unit"] for u in probe["compile"]["order"] if u["unit"].endswith("master_pkg"))
    gp = next(u["unit"] for u in probe["compile"]["order"] if "globals" in u["unit"])
    item, agent, acfg = f"{pk}::{r['item']}", f"{pk}::{r['agent']}", f"{pk}::{r['agent_config']}"
    wq, rq, cfg = m["write_sequencer"], m["read_sequencer"], m["agent_config"]
    return hdr + f'''// The VIP adapter: the single place that knows the VIP ({r['agent']}). The rest of the testbench sees dut_axi_txn and `send` only.
class dut_vip_write_seq extends uvm_sequence #({item});
  `uvm_object_utils(dut_vip_write_seq)
  dut_axi_txn t;
  function new(string name = "dut_vip_write_seq");
    super.new(name);
  endfunction
  task body();
    {item} req = {item}::type_id::create("req");
    start_item(req);
    req.tx_type       = {gp}::WRITE;
    req.transfer_type = {gp}::NON_OUTSTANDING_WRITE;
    void'($cast(req.awid, t.id));
    req.awaddr = t.addr;
    req.awlen  = t.len;
    void'($cast(req.awsize, t.size));
    void'($cast(req.awburst, t.burst));
    req.wdata = {{}};
    req.wstrb = {{}};
    foreach (t.data[i]) req.wdata.push_back(t.data[i]);
    foreach (t.strb[i]) req.wstrb.push_back(t.strb[i]);
    req.no_of_wait_states = 0;
    finish_item(req);
  endtask
endclass

class dut_vip_read_seq extends uvm_sequence #({item});
  `uvm_object_utils(dut_vip_read_seq)
  dut_axi_txn t;
  function new(string name = "dut_vip_read_seq");
    super.new(name);
  endfunction
  task body();
    {item} req = {item}::type_id::create("req");
    start_item(req);
    req.tx_type       = {gp}::READ;
    req.transfer_type = {gp}::NON_OUTSTANDING_READ;
    void'($cast(req.arid, t.id));
    req.araddr = t.addr;
    req.arlen  = t.len;
    void'($cast(req.arsize, t.size));
    void'($cast(req.arburst, t.burst));
    req.no_of_wait_states = 0;
    finish_item(req);
  endtask
endclass

class dut_axi_adapter extends uvm_component;
  `uvm_component_utils(dut_axi_adapter)
  {agent} vip_agent;
  {acfg} vip_cfg;
  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction
  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    vip_cfg = {acfg}::type_id::create("vip_cfg");
    vip_cfg.is_active = UVM_ACTIVE;   // the VIP plays the master; the DUT is the slave (binding: vip_agent_role master)
    vip_cfg.has_coverage = {binding['agent_cfg']['has_coverage']};
    vip_cfg.master_min_addr_range(0, 0);
    vip_cfg.master_max_addr_range(0, '1);
    vip_agent = {agent}::type_id::create("vip_agent", this);
    vip_agent.{cfg} = vip_cfg;
  endfunction
  // Drive one transaction through the VIP master and return when the VIP has finished it (non-outstanding transfer: one at a time).
  task send(dut_axi_txn t);
    if (t.is_write) begin
      dut_vip_write_seq s = dut_vip_write_seq::type_id::create("wr");
      s.t = t;
      s.start(vip_agent.{wq});
    end else begin
      dut_vip_read_seq s = dut_vip_read_seq::type_id::create("rd");
      s.t = t;
      s.start(vip_agent.{rq});
    end
  endtask
endclass
'''


def tb_top_block(probe: dict, vip_dir: Path) -> str:
    vif = probe["interface"]["name"]
    bfm = next(n for n in probe["compile"]["roots"] if n.endswith("agent_bfm"))
    p = "#(.MASTER_ID(0)) " if "MASTER_ID" in (vip_dir / probe["units"][bfm]["file"]).read_text(errors="replace") else ""
    return (f"  {vif} vip_if(.aclk({{CLK}}), .aresetn({{RST}}));\n  {bfm} {p}u_vip_master_bfm(vip_if);\n  dut_axi_bridge u_axi_bridge(.vip(vip_if), .pins(pins));\n")


def filelist_lines(probe: dict, binding: dict, vip_root: str) -> list[str]:
    """VIP files of the compile closure, with the derived constants package in place of the VIP's own (when overridden)."""
    ov = binding.get("override_package")
    first = ["+incdir+./vip_cfg"] if any(x.get("type") == "include" for x in binding.get("substitutions", [])) else []  # a stand-in include is found first
    out = first + [f"+incdir+{vip_root}/{d}" for d in probe["compile"]["incdirs"]]
    subs = {x["unit"]: x["stand_in"] for x in binding.get("substitutions", []) if x.get("type") == "unit"}
    for u in probe["compile"]["order"]:
        if u["unit"] in subs:
            out.append(subs[u["unit"]])
        elif ov and u["unit"] == ov["unit"]:
            out.append("vip_cfg/axi4_globals_pkg.sv")
        else:
            out.append(f"{vip_root}/{u['file']}")
    return out
